import hashlib
import unittest
from dataclasses import FrozenInstanceError

from thresholdsign import (
    AggregateSignature,
    HistoryDeltaSegmentsSeal,
    HistoryDeltaSegmentsSealChain,
    decode_hdsc,
    encode_hdsc,
    encode_hds,
    hdsc_message,
    verify_hdsc,
    verify_signature,
)

from test_nonce_reuse import FIELD_PRIME, GENERATOR, GROUP_PRIME
